@echo off
setlocal enabledelayedexpansion

:: Request admin
net session >nul 2>&1
if %errorlevel% neq 0 (
    echo Requesting admin privileges...
    powershell -Command "Start-Process '%~f0' -Verb RunAs"
    exit /b
)

:: HsMod Restore Script
:: Usage: double-click, or: hsmod_restore.bat D:\backup "C:\Program Files (x86)\Hearthstone"

set "BACKUP_DIR=%~1"
if "%BACKUP_DIR%"=="" set "BACKUP_DIR=%~dp0hsmod_backup"

if not exist "%BACKUP_DIR%\BepInEx" (
    echo [ERROR] Backup folder not found: %BACKUP_DIR%
    echo Place backup folder next to this script, or specify path:
    echo   hsmod_restore.bat D:\hsmod_backup
    pause
    exit /b 1
)

:: Auto-detect Hearthstone path
set "HS_DIR="

for /f "tokens=2*" %%a in ('reg query "HKLM\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\Hearthstone" /v InstallLocation 2^>nul') do set "HS_DIR=%%b"
if not defined HS_DIR (
    for /f "tokens=2*" %%a in ('reg query "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Hearthstone" /v InstallLocation 2^>nul') do set "HS_DIR=%%b"
)

if not defined HS_DIR (
    if exist "C:\Program Files (x86)\Hearthstone" (
        set "HS_DIR=C:\Program Files (x86)\Hearthstone"
    ) else if exist "C:\Program Files\Hearthstone" (
        set "HS_DIR=C:\Program Files\Hearthstone"
    ) else if exist "D:\Hearthstone" (
        set "HS_DIR=D:\Hearthstone"
    )
)

if not defined HS_DIR (
    echo [ERROR] Hearthstone not found. Make sure it's installed.
    echo Or specify manually: hsmod_restore.bat D:\backup "C:\Program Files (x86)\Hearthstone"
    pause
    exit /b 1
)

if not "%~2"=="" set "HS_DIR=%~2"

if not exist "%HS_DIR%\Hearthstone.exe" (
    echo [ERROR] Hearthstone.exe not found at: %HS_DIR%
    pause
    exit /b 1
)

echo.
echo   Backup : %BACKUP_DIR%
echo   HS Path: %HS_DIR%
echo.

if exist "%HS_DIR%\BepInEx" (
    echo [INFO] Existing BepInEx detected, will merge (other plugins preserved)
    echo.
)

echo Restoring...

robocopy "%BACKUP_DIR%\BepInEx" "%HS_DIR%\BepInEx" /E /NFL /NDL /NJH /NJS /NC /NS /NP /IS /IT
echo   [OK] BepInEx\

if exist "%BACKUP_DIR%\doorstop_config.ini" (
    copy /Y "%BACKUP_DIR%\doorstop_config.ini" "%HS_DIR%\" >nul
    echo   [OK] doorstop_config.ini
)

if exist "%BACKUP_DIR%\winhttp.dll" (
    copy /Y "%BACKUP_DIR%\winhttp.dll" "%HS_DIR%\" >nul
    echo   [OK] winhttp.dll
)

echo.
echo ========================================
echo   Done! HsMod restored successfully.
echo ========================================
echo.
echo Launch Hearthstone to take effect. First launch may be slower as BepInEx initializes.
echo.
pause

